  .base1 .foo,
  .base1 .bar {
    color: red;
  }

  .base2 .bar .base2-foo {
    color: red;
  }
}

@tailwind utilities;
@layer utilities {
  .foo.bar.baz {
    color: red;
  }
  .foo1 .bar1 .baz1 {
    color: red;
  }
}

@tailwind utilities;
@layer utilities {
  :where(.foo) {
    color: red;
  }
  :is(.foo, .bar, .baz) {
    color: orange;
  }
  :is(.foo) {
    color: yellow;
  }
  html:has(.foo) {
    color: green;
  }
}

:where(.foo) {
  color: red;
}
:is(.foo, .bar, .baz) {
  color: orange;
}
.foo {
  color: #ff0;
}
html:has(.foo) {
  color: green;
}
:where(.hover\:foo:hover) {
  color: red;
}
:is(.hover\:foo:hover, .bar, .baz),
:is(.foo, .hover\:bar:hover, .baz),
:is(.foo, .bar, .hover\:baz:hover) {
  color: orange;
}
.hover\:foo:hover {
  color: #ff0;
}
html:has(.hover\:foo:hover) {
  color: green;
}
@media (min-width: 640px) {
  :where(.sm\:foo) {
    color: red;
  }
  :is(.sm\:foo, .bar, .baz),
  :is(.foo, .sm\:bar, .baz),
  :is(.foo, .bar, .sm\:baz) {
    color: orange;
  }
  .sm\:foo {
    color: #ff0;
  }
  html:has(.sm\:foo) {
    color: green;
  }
}

